programs.haiku:
"""Layer 15 MLP down_proj, component 323: the comma that closes a sentence-opening phrase.

What it responds to: a comma that ends an introductory phrase at the start of a sentence,
just before the main clause's subject. Typical cases:
  "As an AI assistant[,] my goal is ..."     (strongly negative)
  "Like many composers of that genre[,] he ..."  (strongly negative)
  "Unlike Martin[,] Boros said ..."           (strongly negative)
  "Founded in 1961[,] it is active ..."       (weaker: opener not in the strong list)
  "Although commonly encountered[,] its ..."  (weaker, same reason)
Commas in lists, after main clauses, or after discourse phrases such as "As a result,"
or "As expected," stay near zero. Phrases that open with a subject pronoun ("As you know,")
are also near zero, since they are clauses rather than descriptive phrases.

Most of the component's variance is small, unpredictable noise, so this program explains
only a little of it. Its sign and rough size on the commas it names are right.

The program tracks the current sentence (reset at a newline or at . ! ?, and at each new
document), counts its commas, and remembers its first words. At the first comma of a
sentence it predicts:
  - a negative value if the sentence opens with "As", "Like", "Unlike" or "Compared"
    (a role or description phrase), and the phrase's last word is a person noun
    (WordNet: e.g. director, student, assistant), -8;
  - the same opening, with a non-person last word, -4;
  - another descriptive opener ("Although", "While", "With", "Born", ...), -2;
  - 0 otherwise, including when the next word is a subject pronoun.
"""
import re

import wordnet

READS = ()

COMMAS = {",", "，", "、"}
ENDS = {".", "!", "?", "。", "！", "？"}
# openers that introduce a description of the main clause's subject ("As a ..., he ...")
STRONG = {"as", "like", "unlike", "compared"}
# other descriptive or participial openers
INTRO = {"although", "while", "with", "among", "despite", "being", "born", "founded",
         "based", "orphaned", "having", "given"}
# a subject pronoun right after the opener means a clause, not a phrase
PRONOUNS = {"i", "you", "we", "they", "he", "she", "it", "there", "this", "these", "that"}


def fresh(doc):
    return {"doc": doc, "n": 0, "words": [], "ncom": 0}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    st = carry if carry is not None and carry["doc"] == doc else fresh(doc)
    s = tok.strip()
    val = 0.0
    if s in COMMAS and st["ncom"] == 0 and st["words"] and st["n"] <= 20:
        words = st["words"]
        first = words[0].lower()
        second = words[1].lower() if len(words) > 1 else ""
        if second not in PRONOUNS:
            if first in STRONG:
                head = re.sub(r"[^A-Za-z]", "", words[-1]).lower()
                person = bool(head) and wordnet.is_a(head, "person")
                val = -8.0 if person else -4.0
            elif first in INTRO:
                val = -2.0
    if s in COMMAS:
        st["ncom"] += 1
    if "\n" in tok or s in ENDS:
        st.update(n=0, words=[], ncom=0)
    else:
        st["n"] += 1
        if s:
            st["words"].append(s)
    return st, val

"""Noun-phrase opener detector: fires on the first word or two after "the", "a", "an".

Component p-82af68dd@100000/layers.15.mlp.down_proj:335 is one piece of a layer-15 MLP output.
Its output direction, read through the unembedding, promotes singular nouns that often take
an "of" complement ("the [aspect] of", "the [portion] of", "the [unit] of"). Its activation
is large on the first content word after an article (a noun, adjective or other word that
starts a noun phrase: "the [process] of", "a [person]"), about two-thirds as large on the
second word after it, and it fades within about four words. The article itself, function
words and words far from any article sit near zero, with a small positive background.

The program counts the words since the last article or possessive ("its", "their", ...) in
the same document; the count resets at each document boundary. A word's value is a table
entry for its distance from that opener (content words and function words have separate
tables), scaled by the opener's weight: a capitalised sentence-initial "The" is strongest,
"the" is medium, "a" and "an" are weaker, and possessives are weakest.
"""

ARTICLES = {"the", "a", "an"}
POSSESSIVES = {"your", "its", "his", "her", "my", "our", "their"}
FUNCTION_WORDS = {
    "of", "in", "on", "at", "to", "for", "with", "by", "from", "as", "into", "about",
    "over", "under", "between", "through", "during", "and", "or", "but", "so", "if",
    "because", "while", "when", "where", "is", "are", "was", "were", "be", "been", "being",
    "have", "has", "had", "do", "does", "did", "will", "would", "can", "could", "should",
    "may", "might", "must", "it", "he", "she", "we", "they", "me", "him", "us", "them",
    "who", "whom", "which", "what", "not", "than", "then", "there", "this", "that",
    "these", "those", "some", "any", "every", "each", "my", "your", "his", "her", "its",
    "our", "their", "all", "both", "no", "one", "also", "very", "more", "most",
}

# Activation by how many words after the article (1 = the word right after it).
CONTENT_BY_DISTANCE = {1: 3.2, 2: 2.0, 3: 0.9, 4: 0.45, 5: 0.3, 6: 0.2}
FUNCTION_BY_DISTANCE = {1: 0.6, 2: 0.35}
BACKGROUND = 0.1

READS = ()


def article_weight(raw):
    # Relative strength of the article: "The" that starts a sentence or title is strongest.
    word = raw.strip()
    if word == "The":
        return 1.5
    if word.lower() == "the":
        return 1.0
    if word.lower() in POSSESSIVES:
        return 0.5
    return 0.75


def step(carry, prefix, upstream):
    # carry: (words since the article, article weight) for this position, or None
    # when no article has come yet in this document.
    state = carry
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        state = None
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    value = BACKGROUND
    if state is not None:
        since, weight = state
        if word.isalpha() and word not in FUNCTION_WORDS and word not in ARTICLES | POSSESSIVES:
            value += weight * CONTENT_BY_DISTANCE.get(since, 0.0)
        else:
            value += weight * FUNCTION_BY_DISTANCE.get(since, 0.0)
    if word in ARTICLES or word in POSSESSIVES:
        nxt = (1, article_weight(raw))
    elif state is not None:
        nxt = (state[0] + 1, state[1])
    else:
        nxt = None
    return nxt, float(value)

"""Person-reference detector for MLP unit 339 of layer 15.

The unit is quiet on most text. It rises on words that point at a particular
person in running English prose, mostly news and biography: third-person
pronouns (he, she, him), titles before a name (Mr, Ms, Dr), and speech verbs
that attribute a quote to someone (said, says, told). It is strongest on
"he"/"she"/"said" when a person is the topic of the passage, and it dips
slightly on impersonal determiners (their, its, this, those).

This program gives each position a value from the current word, plus how many
person references fall in the 48 tokens before it in the same document (a
person who has been talked about keeps the unit higher).
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

PRONOUNS = {"he", "she", "him", "himself", "herself"}
POSSESSIVES = {"his", "her"}
TITLES = {"mr", "ms", "mrs", "dr"}
SPEECH = {"said", "says", "told"}
IMPERSONAL = {"their", "its", "this", "these", "those", "whose"}
PERSON_WORDS = PRONOUNS | POSSESSIVES | TITLES
WINDOW = 48


def step(carry, prefix, upstream: Mapping):
    t = prefix.position
    word = prefix.token_strings[t].strip().lower()
    doc = prefix.document_ids[t]
    # person references in the preceding WINDOW tokens of the same document
    lo = max(0, t - WINDOW)
    recent = [
        prefix.token_strings[i].strip().lower()
        for i in range(lo, t)
        if prefix.document_ids[i] == doc
    ]
    density = sum(w in PERSON_WORDS for w in recent) / WINDOW

    if word in PRONOUNS:
        value = 1.0
    elif word in SPEECH:
        value = 1.1
    elif word in TITLES:
        value = 0.5
    elif word in POSSESSIVES:
        value = 0.25
    elif word == "the":
        value = 0.2
    elif word in IMPERSONAL:
        value = -0.17
    else:
        value = 0.05
    return carry, value + 3.0 * density

"""Main verbs about to take an object (layers.15.mlp.down_proj, component 361).

The component pushes the next-token prediction toward a possessive or object
noun phrase ("my", "your", "our"). Its activation is high on a content verb
used as a verb, most of all right after an infinitive marker ("to carry",
"can set", "will make"), less after a subject pronoun, an auxiliary or a
conjunction, and near zero where the word is a noun after a determiner
("the take", "a lose"). Prepositions are slightly negative. Everything else
sits near the average. Predicts one value per token; it reads no other
component and keeps no state beyond the previous token.
"""
from functools import lru_cache

import wordnet

READS = ()

INFINITIVE_MARKERS = {"to", "can", "will", "could", "should", "must", "may", "might", "would", "shall", "cannot", "not", "never", "let"}
SUBJECT_PRONOUNS = {"i", "you", "we", "they", "he", "she", "it", "who", "that"}
CONJUNCTIONS = {"and", "or", "but", "if", "when", "because", "so", "while", "although", "though"}
AUXILIARIES = {"be", "am", "is", "are", "was", "were", "been", "being", "have", "has", "had", "do", "does", "did", "will", "would", "can", "could", "shall", "should", "may", "might", "must", "ll", "ve", "re", "not", "never", "also", "just", "still", "get", "got"}
DETERMINERS = {"the", "a", "an", "this", "these", "those", "my", "your", "our", "his", "her", "its", "their", "some", "any", "each", "every", "no"}
PREPOSITIONS = {"in", "on", "at", "from", "with", "by", "for", "of", "about", "into", "onto", "over", "under", "after", "before", "between", "through", "during", "without", "within", "towards", "toward", "against", "among", "away", "up", "down", "out", "off", "across", "along", "around", "behind", "below", "near", "per", "via", "than", "like", "as", "since", "until"}


@lru_cache(maxsize=None)
def is_content_verb(word):
    """A plain English word that WordNet lists as a verb, and is not an auxiliary."""
    if not word.isalpha() or len(word) < 2 or word in AUXILIARIES:
        return False
    return "verb" in wordnet.parts_of_speech(word)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if is_content_verb(token):
        if before in INFINITIVE_MARKERS:
            value = 1.5
        elif before in SUBJECT_PRONOUNS:
            value = 0.8
        elif before in CONJUNCTIONS or before in AUXILIARIES:
            value = 0.5
        elif before in DETERMINERS:
            value = 0.05
        else:
            value = 0.25
    elif token in PREPOSITIONS and prefix.token_strings[-1].startswith(" "):
        value = -0.1
    else:
        value = 0.05
    return carry, float(value)

"""Layer 15, MLP hidden unit 377 (down_proj component 377), predicted from the tokens so far.

What the component does: it spikes on the word just before a predicate in expository text
(scientific, technical, product copy). The big spikes are on a form of "be" (is, was, were,
are, be, been, being) that follows a noun subject: "background rejection [can] be improved",
"the publication bias [was] conducted", "storage [is] not a problem". The same is true of
Japanese object and subject particles (を, が, は, も). After a pronoun or "there" a "be" form
spikes only weakly ("it is", "this is", "there is"). Modals (can, will, may, must, ...) give a
weaker spike after a noun and none after a pronoun. Every other token predicts 0.

Token identity alone explains only about 12-15% of the variance; the rest depends on the
surrounding text, which this program does not model.
"""

READS = ()

BE = {"is", "are", "was", "were", "be", "been", "being"}
MODAL = {"can", "will", "may", "must", "should", "could", "would", "might", "shall", "has", "have", "had"}
PARTICLE = {"を", "が", "は", "も"}
PRONOUN = {"it", "this", "that", "there", "what", "he", "she", "they", "we", "you", "i", "who", "which", "here"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    previous = ""
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip().lower()
    if word in PARTICLE:
        return carry, 2.3
    if word in BE:
        return carry, 0.9 if previous in PRONOUN else 2.2
    if word in MODAL:
        return carry, 0.0 if previous in PRONOUN else 0.6
    return carry, 0.0

"""Component p-82af68dd@100000/layers.15.mlp.down_proj:379: a file-system path detector.

What it does: it goes negative on the tokens that write out a file-system path or a
directory name, and most strongly when they sit in a shell command the model is writing
inside a <tool_call> (for example `cd /testbed && go test`, or a directory listing with
`build/`, `cmd/`, `api/`). The strongest values are on `cd`, `workspace`, `testbed`,
`directory`, ` &&`, and the slash of a path. Slashes inside a web address (http, www,
.com, ...) are treated as ordinary text and get no value. Other tokens stay near zero,
except a small negative value everywhere inside a tool call or a dense run of path tokens.

The program keeps one piece of state: whether it is inside a <tool_call> block, reset at
each new document. It also counts the path-like tokens among the 16 positions before this
one. The numbers are rounded least-squares fits of these few features to the activations;
the program explains about 11% of the variance, and the rest is noise to it.
"""

READS = ()

# Words that name places in a file system or pieces of a shell command.
PATH_WORDS = {
    "cd", "workspace", "bed", "directory", "dir", "dirs", "folder", "src", "test",
    "tests", "path", "_path", "_dir", "_modules", ".git", "tmp", "pkg", "Dir", "Path", "DIR",
}
URL_MARKS = ("http", "www.", ".com", ".org", ".net", ".edu", ".gov")


def _is_path_token(token):
    """A slash or a path word, as a whole token."""
    return "/" in token or token.strip() in PATH_WORDS


def _in_web_address(text):
    """Whether the current line of text, so far, looks like it holds a web address."""
    line = text.split("\n")[-1][-60:]
    return any(mark in line for mark in URL_MARKS)


def step(carry, prefix, upstream):
    # carry: (inside a <tool_call> block,) from the previous position, or None at a row's start.
    in_tool = bool(carry[0]) if carry else False
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        in_tool = False
    token = prefix.token_strings[-1]
    if token == "<tool_call>":
        in_tool = True

    # Path-like tokens among the 16 positions before this one.
    recent = sum(_is_path_token(t) for t in prefix.token_strings[-17:-1])

    if token.strip() == "&&":
        value = -10.0 if in_tool else -1.2
    elif token.strip() in PATH_WORDS:
        value = -10.0 if in_tool else -3.2
    elif "/" in token and not _in_web_address(prefix.text_prefixes[-1]):
        value = (-4.0 if in_tool else -0.9) - 0.3 * recent
    elif in_tool or recent >= 3:
        value = -0.4 if in_tool else -0.2
    else:
        value = 0.0

    if token == "</tool_call>":
        in_tool = False
    return (in_tool,), value
